import json,sys
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
f=json.load(sys.stdin);out=Path(f['out']);checks=[];errors=[]
with sync_playwright() as p:
 browser=p.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1366,'height':860},timezone_id='Asia/Shanghai');page.on('pageerror',lambda e:errors.append(str(e)))
 def note(s):checks.append(s);print(s,flush=True)
 def nav(name):page.goto(f['base']+'/#/functions/assets/'+name,wait_until='networkidle')
 def state():return page.request.get(f['base']+'/api/state').json()['snapshot']['data']
 def m():return state()['toolManagement']
 def action(key):return page.locator(f'[data-tool-table-action="{key}"]')
 def query(q):page.locator('[name=query]').fill(q);page.locator('[data-tool-query] button[type=submit]').click()
 def select(code,id,clear=True):
  if clear and page.locator('[data-tool-clear-selection]').count():page.locator('[data-tool-clear-selection]').click()
  query(code);page.locator(f'[data-tool-check="asset:{id}"]').check()
 def confirm():page.locator('[data-f=actor]').fill('精简流程经办员');page.locator('[data-modal-confirm]').click();page.locator('.modal').wait_for(state='detached')
 def close():page.locator('.modal [data-modal-cancel]').click()
 def records(kind,id):
  nav('tool-records');page.locator('[data-record-kind]').select_option(kind);page.locator(f'[data-record-id="{id}"]').check();expect(page.locator('[data-record-actions] [data-record-action=return],[data-record-actions] [data-record-action=service-finish],[data-record-actions] [data-record-action=transfer-finish],[data-record-actions] [data-record-action=disposal-review]')).to_have_count(0)
 try:
  nav('tool-register');expect(page.locator('[data-tool-check^="legacy:"]')).to_have_count(0);expect(action('borrow')).to_have_count(0);expect(action('asset-new')).to_be_visible();expect(page.locator('[data-tool-query] [data-tool-table-action]')).to_have_count(0);page.screenshot(path=str(out/'01-default.png'),full_page=True);note('default ledger excludes unregistered stock; no disabled business-button wall')
  page.locator(f'[data-tool-detail="asset:{f["a"]}"]').first.click();expect(page.locator('[data-f]')).to_have_count(0);expect(page.locator('[data-tool-detail-content]')).to_contain_text('入库时间');close();note('name opens read-only dossier including dates and current status')
  select('SIMPLE-A',f['a']);expect(action('borrow')).to_be_visible();expect(action('transfer')).to_be_visible();expect(action('edit')).to_be_visible();assert not page.locator('.tool-unavailable').evaluate('(e)=>e.open');page.screenshot(path=str(out/'02-selected.png'),full_page=True);bounds=page.locator('[data-tool-bottom]').bounding_box();assert bounds['y']+bounds['height']<=865,bounds
  action('edit').click();page.locator('[data-f=tag]').fill('690-SIMPLE-A');confirm();assert next(a for a in m()['assets'] if a['id']==f['a'])['tag']=='690-SIMPLE-A';note('explicit bottom edit preserves CRUD; selection/actions fit desktop')
  select('SIMPLE-A',f['a']);select('SIMPLE-B',f['b'],False);expect(page.locator('[data-tool-hidden-selection]')).to_be_visible();action('borrow').click();page.locator(f'[data-batch-quantity="asset:{f["b"]}"]').fill('2');page.locator('[data-f=borrower]').fill('批量领用人');page.locator('[data-f=dueAt]').fill('2099-01-01T17:00');confirm();expect(page.locator('[data-tool-bottom]')).to_contain_text('待完成业务');action('return').click();page.locator('[data-return-all]').check();page.locator('[data-return-line="1"]').fill('1');page.locator('[data-f=returner]').fill('部分归还人');confirm();loan=next(l for l in m()['loans'] if l['borrower']=='批量领用人' and l['lines'][0]['assetId']==f['b']);assert loan['lines'][0]['returned']==1;note('cross-query multi-selection, borrow and partial return work in ledger')
  select('SIMPLE-C',f['c']);expect(action('transfer-finish')).to_be_visible();action('transfer-finish').click();page.locator('[data-f=decision]').select_option('RECEIVED');confirm();assert next(a for a in m()['assets'] if a['id']==f['c'])['warehouseId']==f['warehouse2'];note('pending transfer receives from dedicated next-step group')
  select('SIMPLE-D',f['d']);expect(action('service-finish')).to_be_visible();page.screenshot(path=str(out/'03-pending-service.png'),full_page=True);action('service-finish').click();page.locator('[data-f=result]').select_option('PASS');page.locator('[data-f=certificate]').fill('SIMPLE-CERT');confirm();assert next(s for s in m()['services'] if s['id']==f['service'])['certificate']=='SIMPLE-CERT';note('inspection result registration and return to stock remain in ledger')
  records('inspection',f['service']);expect(page.locator('[data-record-table]')).to_contain_text('SIMPLE-CERT');expect(page.locator('.tool-record-advanced')).not_to_have_attribute('open','');page.screenshot(path=str(out/'04-records.png'),full_page=True);page.locator('[data-record-actions] [data-record-action=detail-view]').click();expect(page.locator('[data-f]')).to_have_count(0);close();note('records are read-only with dossier and ledger links; advanced filters collapsed')
  records('loans',f['overdue']);page.locator('[data-record-ledger]').click();expect(page.locator('[data-tool-row]')).to_have_count(2);expect(page.locator('[data-tool-check]:checked')).to_have_count(0);assert {r.get_attribute('data-tool-row') for r in page.locator('[data-tool-row]').all()}=={f'asset:{f["kitA"]}',f'asset:{f["kitB"]}'};note('multi-tool document link locates exact members without auto-selection')
  nav('tool-warnings');expect(page.locator('[data-warning-send],[data-warning-check]')).to_have_count(0);page.locator('[name=query]').fill('SIMPLE-EXPIRED');page.locator('[data-warning-query] button[type=submit]').click();page.locator('[data-warning-ledger]').click();expect(page.locator('[data-tool-row]')).to_have_count(1);page.locator(f'[data-tool-check="asset:{f["expired"]}"]').check();expect(action('borrow')).to_have_count(0);expect(action('inspection')).to_be_visible();note('warning locates target in ledger; expired tool only offers applicable business')
  nav('tool-warnings');page.locator('[name=query]').fill('');page.locator('[name=kind]').select_option('overdue');expect(page.locator('[data-warning-return]')).to_have_count(0);page.locator('[data-warning-ledger]').click();expect(page.locator('[data-tool-row]')).to_have_count(2);note('overdue warning navigates to exact loan members instead of duplicating return form')
  nav('tool-register');page.locator('[data-tool-ledger-scope=legacy]').click();assert page.locator('[data-tool-check^="legacy:"]').count()>0;page.locator('[data-tool-check]').first.check();expect(action('adopt')).to_be_visible();expect(action('borrow')).to_have_count(0);page.screenshot(path=str(out/'05-legacy.png'),full_page=True);note('unregistered stock remains discoverable with explicit registration action')
  page.locator('[data-tool-clear-selection]').click();page.locator('[data-tool-ledger-scope=registered]').click();query('SIMPLE-A');page.locator('[data-tool-filter-open=type]').click();expect(page.locator('.tool-filter-options')).not_to_contain_text('待完善登记');close();page.set_viewport_size({'width':390,'height':844});page.locator(f'[data-tool-check="asset:{f["a"]}"]').check();assert not page.evaluate('document.documentElement.scrollWidth>innerWidth+1');page.screenshot(path=str(out/'06-mobile.png'),full_page=True);note('Excel-style filters respect current ledger scope; mobile has no page overflow')
  assert not errors,errors
 finally:
  (out/'results.json').write_text(json.dumps({'checks':checks,'pageErrors':errors,'productionWrites':False},ensure_ascii=False,indent=2),encoding='utf8');browser.close()
